 for l in f.open():
  r=json.loads(l);key=next((k for t,k in tasks.items() if t in r['obs_text_base']),None)
  if key:wanted.add(key)
(base/'rollout_tasks.json').write_text(json.dumps(sorted(wanted)))
print('baseline saved; rollout task keys',sorted(wanted))
