rule(('social_network_9', 9), '''
from datetime import datetime, timezone

def dt(value):
    parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    return (parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None
            else parsed.astimezone(timezone.utc))

initial_posts = {r[0] for r in query(initial_db_path, "SELECT id FROM posts")}
initial_deals = {r[0] for r in query(initial_db_path, "SELECT id FROM business_deals")}
redemption = 'Show this Nextdoor post at checkout to redeem.'
rows = query(final_db_path,
    "SELECT p.id, p.body, d.id, d.title, d.description, d.valid_days_of_week, "
    "d.valid_start_time, d.valid_end_time, d.valid_from, d.valid_until, p.created_at "
    "FROM posts p JOIN business_posts bp ON bp.post_id = p.id "
    "JOIN businesses b ON b.id = bp.business_id "
    "JOIN business_deals d ON d.post_id = p.id AND d.business_id = b.id "
    "WHERE b.name = ? AND b.is_verified = 1 AND p.is_business_post = 1",
    ('Green Leaf Coffee',))
for post_id, body, deal_id, title, description, days, start_time, end_time, valid_from, valid_until, created_at in rows:
    if post_id in initial_posts or deal_id in initial_deals:
        continue
    if redemption not in (body or '') or redemption not in (description or ''):
        continue
    if 'buy 1 get 1 free latte' not in (title or '').lower():
        continue
    # The API accepts both abbreviated weekday names and ISO weekday numbers.
    day_names = {'mon': 'mon', 'monday': 'mon', '1': 'mon',
                 'tue': 'tue', 'tuesday': 'tue', '2': 'tue',
                 'wed': 'wed', 'wednesday': 'wed', '3': 'wed'}
    tokens = [v.strip().lower() for v in (days or '').split(',')]
