rule(('subscription_management_4', 2), r'''
# Match the tool's actual trailing 30-day window, including its upper bound.
# Anchoring at MAX(start_time) incorrectly treats years-old sessions as recent.
if not isinstance(final_answer, str) or not final_answer.strip():
    return {"result": "others"}
plans = query(final_db_path,
    "SELECT sp.max_simultaneous_devices FROM user_subscriptions us "
    "JOIN subscription_plans sp ON sp.id = us.plan_id "
    "WHERE us.user_id = 1 AND us.status = 'active' ORDER BY us.id")
if not plans:
    return {"result": "others"}
maximum = int(plans[0][0])
used = query(final_db_path,
    "SELECT COUNT(DISTINCT device_type) FROM play_sessions WHERE user_id = 1 "
    "AND julianday(start_time) >= julianday('now', '-30 days') "
    "AND julianday(start_time) <= julianday('now')")[0][0]
remaining = max(0, maximum - used)
# Only grade the final assertion when the answer labels one. Numeric tokens
# in task restatements, quotations, or abandoned calculations are not answers.
parts = re.split(r'(?i)\bfinal\s*answer\s*:', final_answer)
text = parts[-1].strip().lower()
number = r'(\d+)'
patterns = [
    r'\b' + number + r'\s+(?:additional|more|extra|remaining|available)\s+devices?\b',
    r'\b' + number + r'\s+devices?\s+(?:remaining|available|left)\b',
    r'\b(?:additional|remaining|available)\s+(?:device\s+)?(?:devices?|slots?)(?:\s+(?:remaining|available|left))?\s*(?:is|are|=|:)\s*' + number + r'\b',
    r'\b(?:can|may)\s+(?:still\s+)?(?:use|add|connect)\s+' + number + r'\s+(?:more\s+|additional\s+)?devices?\b',
    r'\bremaining_device_slots[\s"\x27]*[:=]\s*' + number + r'\b',
]
claims = [int(m.group(1)) for pattern in patterns for m in re.finditer(pattern, text)]
if re.search(r'\bno\s+(?:additional|more|remaining|available)\s+devices?\b', text):
    claims.append(0)
# Accept an explicit arithmetic statement tied to device capacity as well.
for m in re.finditer(r'\b(\d+)\s*[-−]\s*(\d+)\s*=\s*(\d+)\b', text):
    if int(m[1]) == maximum and int(m[2]) == used and 'device' in text:
        claims.append(int(m[3]))
if claims and all(value == remaining for value in claims):
    return {"result": "complete"}
return {"result": "others"}
''')

rule(('fundraising_donations_5', 9), r'''
if not isinstance(final_answer, str) or not final_answer.strip():
    return {"result": "others"}
# Match get_team_leaderboard: both team and campaign scope, every donation,
# descending total, then donation count/name, with sequential displayed ranks.
team_rows = query(final_db_path,
    "SELECT t.id, c.id FROM teams t JOIN campaigns c ON c.id = t.campaign_id "
    "WHERE t.name = ? AND c.name = ?", ('Downtown Champions', '2025 Summer Meal Drive'))
if len(team_rows) != 1:
    return {"result": "others"}
team_id, campaign_id = team_rows[0]
rows = query(final_db_path,
    "SELECT tm.id, tm.name, COALESCE(SUM(d.amount), 0), COUNT(d.id) "
    "FROM team_members tm LEFT JOIN donations d ON d.team_member_id = tm.id "
    "AND d.team_id = ? AND d.campaign_id = ? WHERE tm.team_id = ? "
    "GROUP BY tm.id, tm.name ORDER BY COALESCE(SUM(d.amount), 0) DESC, "
    "COUNT(d.id), tm.name LIMIT 10", (team_id, campaign_id, team_id))
if not rows:
    return {"result": "others"}
text = re.split(r'(?i)\bfinal\s*answer(?:\s*\([^\n]*?\))?\s*:', final_answer)[-1].strip()
expected = {row[0]: (row[1], float(row[2]), int(row[3]), i + 1) for i, row in enumerate(rows)}

# Structured results retain field associations, including donation counts.
try:
    obj = json.loads(re.sub(r'^```(?:json)?\s*|\s*```$', '', text, flags=re.I))
except ValueError:
    obj = None
if isinstance(obj, dict):
    obj = obj.get('members', obj.get('leaderboard', obj.get('results')))
if isinstance(obj, list):
    if len(obj) != len(rows):
        return {"result": "others"}
    for i, (item, row) in enumerate(zip(obj, rows)):
        if not isinstance(item, dict):
            return {"result": "others"}
        name, amount, count, rank = expected[row[0]]
        if str(item.get('name', '')).lower() != name.lower():
            return {"result": "others"}
        if abs(float(item.get('total_raised', -1)) - amount) > 0.01:
            return {"result": "others"}
        if int(item.get('donation_count', item.get('num_donations', -1))) != count or int(item.get('rank', -1)) != rank:
            return {"result": "others"}
    return {"result": "complete"}

# In prose or a table, each member needs their own amount, count and rank.
# The old global numeric search let another member's numbers satisfy a row.
positions = []
for i, row in enumerate(rows):
    member_id, name, amount, count = row
    matches = list(re.finditer(r'(?<!\w)' + re.escape(name) + r'(?!\w)', text, re.I))
    if len(matches) != 1:
        return {"result": "others"}
    positions.append(matches[0].start())
if positions != sorted(positions):
    return {"result": "others"}
for i, (member_id, name, amount, count) in enumerate(rows):
    start = text.rfind('\n', 0, positions[i]) + 1
    end = text.rfind('\n', 0, positions[i+1]) if i + 1 < len(rows) else len(text)
    segment = text[start:end].replace(',', '')
    # Currency/total labels, or a table cell immediately following the name.
    amount_patterns = [r'\$\s*(\d+(?:\.\d+)?)',
        r'(?:total[_\s]*raised|raised|amount)\s*[=:]?\s*\$?\s*(\d+(?:\.\d+)?)',
        re.escape(name) + r'\s*\|\s*\$?\s*(\d+(?:\.\d+)?)']
    amounts = [float(m.group(1)) for p in amount_patterns for m in re.finditer(p, segment, re.I)]
    if not amounts or any(abs(v - float(amount)) > 0.01 for v in amounts):
        return {"result": "others"}
    count_patterns = [r'(?:donation[_\s]*count|num[_\s]*donations|donations?)\s*[=:]?\s*(\d+)\b',
                      r'\b(\d+)\s+donations?\b']
    counts = [int(m.group(1)) for p in count_patterns for m in re.finditer(p, segment, re.I)]
    ranks = [int(m.group(1)) for m in re.finditer(r'\brank\s*[#=:]?\s*(\d+)\b', segment, re.I)]
    prefix = segment[:segment.lower().find(name.lower())]
    numbered = re.search(r'^\s*(?:[-*]\s*)?#?(\d+)\s*[.)|:–—-]', prefix)
    if numbered:
        ranks.append(int(numbered[1]))
    if '|' in segment:
        # Markdown columns: Rank | Member | Total raised | Donations.
        cells = [c.strip() for c in segment.split('|') if c.strip()]
        name_index = next((j for j, cell in enumerate(cells) if name.lower() == cell.lower()), -1)
        if name_index >= 1 and cells[name_index-1].isdigit():
            ranks.append(int(cells[name_index-1]))
        if name_index >= 0 and len(cells) > name_index + 2 and cells[name_index+2].isdigit():
            counts.append(int(cells[name_index+2]))
    if not counts or any(v != int(count) for v in counts) or not ranks or any(v != i+1 for v in ranks):
        return {"result": "others"}
return {"result": "complete"}
''')

rule(('dating_matchmaking_3', 3), r'''
if not isinstance(final_answer, str) or not final_answer.strip():
    return {"result": "others"}
rows = query(final_db_path,
    "SELECT candidate_user_id, distance_miles, compatibility_score "
    "FROM match_candidates WHERE user_id = 1 AND distance_miles <= 15 "
    "AND compatibility_score > 80 AND reason_dog_compatibility = 1 "
    "AND reason_shared_outdoors_lifestyle = 1 ORDER BY compatibility_score DESC LIMIT 10")
text = re.split(r'(?i)\bfinal\s*answer\s*:', final_answer)[-1].strip()
try:
    obj = json.loads(re.sub(r'^```(?:json)?\s*|\s*```$', '', text, flags=re.I))
except ValueError:
    obj = None
if isinstance(obj, dict):
    obj = obj.get('match_candidates', obj.get('candidates', obj.get('results')))
if isinstance(obj, list):
    if len(obj) != len(rows):
        return {"result": "others"}
    for item, (cid, distance, score) in zip(obj, rows):
        if not isinstance(item, dict) or int(item.get('candidate_user_id', -1)) != cid:
            return {"result": "others"}
        if 'compatibility_score' in item and abs(float(item['compatibility_score']) - score) > 0.001:
            return {"result": "others"}
        if 'distance_miles' in item and abs(float(item['distance_miles']) - distance) > 0.001:
            return {"result": "others"}
        if any(key in item and item[key] not in (True, 1) for key in
               ('reason_dog_compatibility', 'reason_shared_outdoors_lifestyle')):
            return {"result": "others"}
    return {"result": "complete"}
if not rows:
    return {"result": "complete" if re.search(r'(?i)\b(no|zero)\s+(?:matching\s+)?candidates?\b', text) else "others"}
# Read IDs from candidate labels or rows rather than matching arbitrary
# numbers (list indices and distances are not user IDs).
id_pattern = r'(?i)["\x27]?candidate(?:[_\s]+user)?(?:[_\s]+id)?["\x27]?\s*[:=#]?\s*(\d+)\b'
mentions = list(re.finditer(id_pattern, text))
if not mentions:
    # Also support a labelled Markdown table with candidate IDs in its first
    # column; an optional first column may be the displayed rank.
    lines = text.splitlines()
    table_rows = []
    for line in lines:
        cells = [c.strip() for c in line.strip().strip('|').split('|')]
